// Generated by scripts/symbology/gen_app6d_catalog.py (APP-6D tables plus
// Delta's Ukrainian object types) and shared with the agent's Python library.

export type CatalogCode = { code: string; name: string; uk: string };
/** `uk`/`ukPath` come from Delta's object-type dictionary when Delta knows the entity. */
export type CatalogEntity = {
  code: string;
  name: string;
  path: string[];
  uk?: string;
  ukPath?: string[];
  delta?: boolean;
  /** False when milsymbol cannot draw the entity; `deltaIcon` then says whether
   * Delta's exported icon covers it. */
  drawable?: boolean;
  deltaIcon?: boolean;
};
export type CatalogSymbolSet = {
  code: string;
  name: string;
  uk: string;
  entities: CatalogEntity[];
  modifier1: Array<{ code: string; name: string }>;
  modifier2: Array<{ code: string; name: string }>;
};
export type CatalogAlias = {
  label: string;
  terms: string[];
  symbolSet: string;
  entity: string;
  modifier1: string;
  modifier2: string;
  hq: string;
  english: string;
};
export type App6dCatalog = {
  identities: CatalogCode[];
  statuses: CatalogCode[];
  hqTfDummy: CatalogCode[];
  echelons: CatalogCode[];
  mobility: CatalogCode[];
  symbolSets: CatalogSymbolSet[];
  aliases: CatalogAlias[];
};

/** A symbol type: everything in a SIDC except identity, status, HQ and echelon. */
export type SymbolType = {
  symbolSet: string;
  entity: string;
  modifier1: string;
  modifier2: string;
  label: string;
  detail: string;
};

export type SidcParts = {
  version: string;
  context: string;
  identity: string;
  symbolSet: string;
  status: string;
  hq: string;
  echelon: string;
  entity: string;
  modifier1: string;
  modifier2: string;
};

const CATALOG_URL = '/data/app6d-catalog.json';
let catalogLoad: Promise<App6dCatalog> | null = null;

export function loadCatalog(): Promise<App6dCatalog> {
  catalogLoad ??= fetch(CATALOG_URL).then((response) => {
    if (!response.ok) throw new Error(`APP-6D catalog: HTTP ${response.status}`);
    return response.json() as Promise<App6dCatalog>;
  });
  catalogLoad.catch(() => {
    catalogLoad = null;
  });
  return catalogLoad;
}

export function sidcParts(sidc: string): SidcParts {
  return {
    version: sidc.slice(0, 2),
    context: sidc.slice(2, 3),
    identity: sidc.slice(3, 4),
    symbolSet: sidc.slice(4, 6),
    status: sidc.slice(6, 7),
    hq: sidc.slice(7, 8),
    echelon: sidc.slice(8, 10),
    entity: sidc.slice(10, 16),
    modifier1: sidc.slice(16, 18),
    modifier2: sidc.slice(18, 20),
  };
}

export function joinSidc(parts: SidcParts): string {
  return [
    parts.version,
    parts.context,
    parts.identity,
    parts.symbolSet,
    parts.status,
    parts.hq,
    parts.echelon,
    parts.entity,
    parts.modifier1,
    parts.modifier2,
  ].join('');
}

function normalize(text: string): string {
  return text.toLowerCase().replace(/[’ʼ]/g, "'").replace(/\s+/g, ' ').trim();
}

function findEntity(catalog: App6dCatalog, symbolSet: string, entity: string) {
  const set = catalog.symbolSets.find((item) => item.code === symbolSet);
  return { set, entity: set?.entities.find((item) => item.code === entity) };
}

function entityType(set: CatalogSymbolSet, entity: CatalogEntity): SymbolType {
  const parents = (entity.ukPath ?? entity.path).slice(0, -1);
  return {
    symbolSet: set.code,
    entity: entity.code,
    modifier1: '00',
    modifier2: '00',
    label: entity.uk ?? entity.name,
    detail: [set.uk, ...parents].join(' · '),
  };
}

/** A curated alias, described by Delta's Ukrainian path when Delta knows it. */
function aliasType(catalog: App6dCatalog, alias: CatalogAlias): SymbolType {
  const { set, entity } = findEntity(catalog, alias.symbolSet, alias.entity);
  return {
    symbolSet: alias.symbolSet,
    entity: alias.entity,
    modifier1: alias.modifier1,
    modifier2: alias.modifier2,
    label: alias.label,
    detail: set && entity?.ukPath ? entityType(set, entity).detail : alias.english,
  };
}

/** Curated aliases first, then Delta/APP-6D entities ranked by how well their
 * Ukrainian (or English) name matches. */
export function searchSymbolTypes(catalog: App6dCatalog, query: string, limit = 30): SymbolType[] {
  const needle = normalize(query);
  const results: SymbolType[] = [];
  const seen = new Set<string>();
  const push = (item: SymbolType) => {
    const key = `${item.symbolSet}:${item.entity}:${item.modifier1}:${item.modifier2}`;
    if (seen.has(key)) return;
    seen.add(key);
    results.push(item);
  };
  const score = (names: string[], context: string) => {
    const words = names.map(normalize);
    if (words.some((word) => word === needle)) return 0;
    if (words.some((word) => word.startsWith(needle))) return 1;
    if (words.some((word) => word.includes(needle))) return 2;
    return normalize(context).includes(needle) ? 3 : 4;
  };
  const aliases = needle
    ? catalog.aliases
        .map((alias, index) => ({
          alias,
          index,
          score: score([alias.label, ...alias.terms], alias.english),
        }))
        .filter((item) => item.score < 3)
        .sort((a, b) => a.score - b.score || a.index - b.index)
        .map((item) => item.alias)
    : catalog.aliases;
  for (const alias of aliases) push(aliasType(catalog, alias));
  if (!needle) return results.slice(0, limit);
  const entities = catalog.symbolSets.flatMap((set) =>
    set.entities
      // Types nothing can draw would only show a placeholder.
      .filter((entity) => entity.drawable !== false || entity.deltaIcon)
      .map((entity) => ({
        type: entityType(set, entity),
        score: score(
          [entity.uk ?? '', entity.name],
          [...(entity.ukPath ?? []), ...entity.path, set.uk].join(' '),
        ),
        delta: entity.delta ? 0 : 1,
      })),
  );
  entities
    .filter((item) => item.score < 4)
    .sort(
      (a, b) => a.score - b.score || a.delta - b.delta || a.type.label.length - b.type.label.length,
    )
    .forEach((item) => push(item.type));
  return results.slice(0, limit);
}

function codeLabel(items: CatalogCode[], code: string): string {
  return items.find((item) => item.code === code)?.uk ?? code;
}

/** "Ворожий · БпЛА" style label for lists and tooltips. */
export function describeSidc(catalog: App6dCatalog | null, sidc: string): string {
  if (!/^\d{20}$/.test(sidc)) return sidc;
  const parts = sidcParts(sidc);
  if (!catalog) return sidc;
  const alias = catalog.aliases.find(
    (item) =>
      item.symbolSet === parts.symbolSet &&
      item.entity === parts.entity &&
      item.modifier1 === parts.modifier1,
  );
  const { set, entity } = findEntity(catalog, parts.symbolSet, parts.entity);
  const type =
    alias?.label ?? entity?.uk ?? entity?.name ?? set?.uk ?? `${parts.symbolSet}/${parts.entity}`;
  const pieces = [codeLabel(catalog.identities, parts.identity), type];
  if (parts.status !== '0') pieces.push(codeLabel(catalog.statuses, parts.status));
  if (parts.echelon !== '00')
    pieces.push(codeLabel([...catalog.echelons, ...catalog.mobility], parts.echelon));
  return pieces.join(' · ');
}

export function symbolTypeOf(catalog: App6dCatalog | null, sidc: string): SymbolType {
  const parts = sidcParts(sidc);
  const alias = catalog?.aliases.find(
    (item) =>
      item.symbolSet === parts.symbolSet &&
      item.entity === parts.entity &&
      item.modifier1 === parts.modifier1,
  );
  if (alias) return aliasType(catalog!, alias);
  const { set, entity } = catalog
    ? findEntity(catalog, parts.symbolSet, parts.entity)
    : { set: undefined, entity: undefined };
  if (set && entity) {
    return { ...entityType(set, entity), modifier1: parts.modifier1, modifier2: parts.modifier2 };
  }
  return {
    symbolSet: parts.symbolSet,
    entity: parts.entity,
    modifier1: parts.modifier1,
    modifier2: parts.modifier2,
    label: `${parts.symbolSet}/${parts.entity}`,
    detail: set?.uk ?? '',
  };
}
